class Runnable:
    def invoke(self, x):
        raise NotImplementedError

    def batch(self, xs):
        return [self.invoke(x) for x in xs]

    def __or__(self, other):
        return RunnableSequence(self, coerce(other))

    def __ror__(self, other):
        return RunnableSequence(coerce(other), self)


class RunnableLambda(Runnable):
    def __init__(self, fn):
        self.fn = fn

    def invoke(self, x):
        return self.fn(x)


class RunnableSequence(Runnable):
    def __init__(self, first, second):
        self.first = first
        self.second = second

    def invoke(self, x):
        return self.second.invoke(self.first.invoke(x))


class RunnableParallel(Runnable):
    def __init__(self, **steps):
        self.steps = {name: coerce(step) for name, step in steps.items()}

    def invoke(self, x):
        return {name: step.invoke(x) for name, step in self.steps.items()}


class RunnablePassthrough(Runnable):
    def invoke(self, x):
        return x

    @classmethod
    def assign(cls, **steps):
        runnables = {name: coerce(step) for name, step in steps.items()}

        def add(x):
            if not isinstance(x, dict):
                raise TypeError("assign needs a dict input")
            merged = dict(x)
            for name, step in runnables.items():
                merged[name] = step.invoke(x)
            return merged

        return RunnableLambda(add)


def coerce(obj):
    if isinstance(obj, Runnable):
        return obj
    if isinstance(obj, dict):
        return RunnableParallel(**obj)
    if callable(obj):
        return RunnableLambda(obj)
    raise TypeError(f"cannot compose {type(obj).__name__} into a chain")
